mapper.select:
SELECT *
FROM activity
WHERE id = #{activityId}
  AND user_id = #{userId}
  AND deleted_at IS NULL

SELECT id, title, category, organizer, audience_scope, enroll_deadline, published_at, location,max_participants,
CASE WHEN status IN (0, 1, 5, 6, 7) THEN status WHEN NOW() >= end_time THEN 4 WHEN NOW() >= start_time THEN 3 ELSE 2 END AS status
FROM activity WHERE status = #{status} AND deleted_at IS NULL
AND category = #{category}
AND MATCH(title, content, organizer) AGAINST(#{keyword} IN BOOLEAN MODE)
AND id < #{lastId}
ORDER BY id, published_at DESC LIMIT #{limit}

SELECT COALESCE(view_count, 0)
FROM activity
WHERE id = #{id}

mapper.update:
UPDATE activity
SET is_pinned = #{pinned}
WHERE id = #{activityId}
  AND status IN (2, 3)
  AND NOW() < end_time
  AND deleted_at IS NULL

UPDATE activity
SET view_count = COALESCE(view_count, 0) + #{delta}
WHERE id = #{id}
